public class ImageTilerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src =
                    new java.awt.image.BufferedImage(2, 1, java.awt.image.BufferedImage.TYPE_INT_RGB);
            src.setRGB(0, 0, 0x336699);
            src.setRGB(1, 0, 0xCC2200);
            java.awt.image.BufferedImage result = ImageTiler.tile(src, 3, 2);
            check("tile returns an image", true, result != null);
            if (result != null) {
                check("tiled width", 6, result.getWidth());
                check("tiled height", 2, result.getHeight());
                check("copy 0 left pixel (0,0)", "#336699", pixel(result, 0, 0));
                check("copy 0 right pixel (1,0)", "#CC2200", pixel(result, 1, 0));
                check("copy 1 left pixel (2,0)", "#336699", pixel(result, 2, 0));
                check("second row last pixel (5,1)", "#CC2200", pixel(result, 5, 1));
            }
            check("src left pixel unchanged", "#336699", pixel(src, 0, 0));
            check("src size unchanged", "2x1", src.getWidth() + "x" + src.getHeight());
