import java.awt.image.BufferedImage;

public class ImageTiler {

    public static BufferedImage tile(BufferedImage src, int cols, int rows) {
        BufferedImage out = new BufferedImage(
                src.getWidth() * cols, src.getHeight() * rows, BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = out.createGraphics();
        try {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    g.drawImage(src, c * src.getWidth(), r * src.getHeight(), null);
                }
            }
        } finally {
            g.dispose();
        }
        return out;
    }
}
